import '@testing-library/jest-dom/vitest'

import { render, screen, waitFor } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'

const mocks = vi.hoisted(() => ({
  getNotifications: vi.fn(),
  markNotificationRead: vi.fn().mockResolvedValue({ data: {} }),
}))
vi.mock('../../services/apiClient', () => ({ threePortalApi: mocks }))

import { NotificationsPage } from './NotificationsPage'

describe('NotificationsPage mark-read', () => {
  it('marks a notification as read', async () => {
    mocks.getNotifications.mockResolvedValue({
      data: [
        { id: 'n-1', type: 'APPOINTMENT_STATUS_CHANGED', title: 'Appointment confirmed', body: 'Your appointment was confirmed.', linkPath: null, readAt: null, createdAt: new Date().toISOString() },
      ],
    })

    render(<NotificationsPage />)

    const markReadButton = await screen.findByText('Mark read')
    markReadButton.click()

    await waitFor(() => expect(mocks.markNotificationRead).toHaveBeenCalledWith('n-1'))
    await waitFor(() => expect(screen.queryByText('Mark read')).not.toBeInTheDocument())
  })
})
